  body[data-page="index.html"] > main > #kanzlei .quote-card {
    min-height: 200px;
    padding-block: 18px;
    gap: 16px;
  }
}


/* logo.css */
/* CVM TAX · Originales SVG-Logo. Nur Markendarstellung und ihre Bildmaße. */
.nav .brand[data-cvm-logo] {
  display: inline-flex;
  align-items: center;
  min-width: 0;
  flex-shrink: 0;
  line-height: 1;
}
.nav .brand[data-cvm-logo] .cvm-logo {
  display: block;
  width: 166px;
  height: auto;
}
footer .footer-brand[data-cvm-logo] {
  display: inline-flex;
  align-items: center;
  line-height: 1;
}
footer .footer-brand[data-cvm-logo] .cvm-logo {
  display: block;
  width: 132px;
  height: auto;
}
@media (max-width: 759px) {
  .nav .brand[data-cvm-logo] .cvm-logo {
    width: clamp(106px, 28vw, 166px);
  }
}


