/* Hero trust card: same glass controls, neutral transparent fill, unchanged geometry. */
#cvm-design-preview[data-glass="strong"]{--cvm-trust-alpha:.10;--cvm-trust-night-alpha:.74;}
#cvm-design-preview[data-glass]:not([data-glass="original"]) #top > .hero .trustline{
 background:linear-gradient(135deg,rgba(255,255,255,var(--cvm-glint)),rgba(255,255,255,0) 58%),rgba(255,255,255,var(--cvm-trust-alpha)) !important;
 border-color:rgba(255,255,255,var(--cvm-edge)) !important;
 box-shadow:inset 0 1px 0 rgba(255,255,255,.84),inset 0 -1px 0 rgba(255,255,255,.18),0 12px 32px rgba(24,35,44,var(--cvm-shadow)) !important;
 backdrop-filter:blur(var(--cvm-blur)) saturate(100%) !important;
 -webkit-backdrop-filter:blur(var(--cvm-blur)) saturate(100%) !important;
}
#cvm-design-preview[data-glass]:not([data-glass="original"])[data-glass-night="true"] #top > .hero .trustline{
 background:linear-gradient(135deg,rgba(255,255,255,.04),rgba(255,255,255,0) 58%),rgba(255,255,255,var(--cvm-trust-night-alpha)) !important;
}
@supports not ((backdrop-filter:blur(1px)) or (-webkit-backdrop-filter:blur(1px))){
 #cvm-design-preview[data-glass]:not([data-glass="original"]) #top > .hero .trustline{background:#F8FAFC !important;backdrop-filter:none !important;-webkit-backdrop-filter:none !important;}
}
@media(prefers-reduced-transparency:reduce){
 #cvm-design-preview[data-glass]:not([data-glass="original"]) #top > .hero .trustline{background:#F8FAFC !important;backdrop-filter:none !important;-webkit-backdrop-filter:none !important;}
}


