/* frostglas-referenz-01.css */
/* Reference variant only. Content, dimensions and the original mode are retained. */
.cvm-frost-scene{display:none;pointer-events:none;user-select:none;}
#cvm-design-preview[data-material="frosted"][data-glass][data-palette][data-background]{--cvm-frost-alpha:.20;--cvm-frost-inner-alpha:.44;--cvm-frost-blur:20px;--cvm-frost-edge:.56;--cvm-frost-shadow:.08;--cvm-frost-shape-alpha:.42;}
#cvm-design-preview[data-material="frosted"][data-glass][data-palette][data-background][data-glass="strong"]{--cvm-frost-alpha:.12;--cvm-frost-inner-alpha:.34;--cvm-frost-blur:28px;--cvm-frost-edge:.64;--cvm-frost-shadow:.11;}
/* One document-sized decorative layer. No fixed/negative layer or section clipping. */
#cvm-design-preview[data-material="frosted"][data-glass][data-palette][data-background] body[data-page="index.html"]{position:relative;}
#cvm-design-preview[data-material="frosted"][data-glass][data-palette][data-background] body[data-page="index.html"]::before{position:absolute !important;inset:0 !important;z-index:0 !important;pointer-events:none;}
#cvm-design-preview[data-material="frosted"][data-glass][data-palette][data-background] body[data-page="index.html"] > :is(main,footer){position:relative;z-index:1;}
#cvm-design-preview[data-material="frosted"][data-glass][data-palette][data-background] #cvm-frost-landscape{display:block;position:absolute;inset:0;z-index:0;overflow:hidden;pointer-events:none;user-select:none;}
/* Defined contours outside glass, softened only by the panel's backdrop blur. */
#cvm-design-preview[data-material="frosted"][data-glass][data-palette][data-background] #cvm-frost-landscape > .cvm-frost-shape{position:absolute;display:block;box-sizing:border-box;pointer-events:none;border-radius:var(--shape-radius,50%);background:radial-gradient(ellipse at 30% 24%,rgba(255,255,255,.58),rgb(var(--cvm-frost-secondary) / .86) 28%,rgb(var(--cvm-frost-rgb) / .67) 76%,rgb(var(--cvm-frost-rgb) / .46) 100%);border:1px solid rgba(255,255,255,.42);box-shadow:inset 0 1px 3px rgba(255,255,255,.60);}
#cvm-design-preview[data-material="frosted"][data-glass][data-palette][data-background] #cvm-frost-landscape > .cvm-frost-shape--wash{border:0;box-shadow:none;background:radial-gradient(ellipse at 48% 50%,rgb(var(--cvm-frost-secondary) / .46),rgb(var(--cvm-frost-rgb) / .20) 40%,rgb(var(--cvm-frost-rgb) / 0) 85%);}
#cvm-design-preview[data-material="frosted"][data-glass][data-palette][data-background] #cvm-frost-landscape > .cvm-frost-shape--arc{border:0;box-shadow:none;background:radial-gradient(ellipse at 50% 50%,rgb(var(--cvm-frost-rgb) / 0) 50%,rgb(var(--cvm-frost-rgb) / .60) 51%,rgb(var(--cvm-frost-secondary) / .86) 59%,rgb(var(--cvm-frost-rgb) / .46) 70%,rgb(var(--cvm-frost-rgb) / 0) 71%);}
#cvm-design-preview[data-material="frosted"][data-glass][data-palette][data-background] #cvm-frost-landscape > .cvm-frost-shape--ribbon{background:linear-gradient(122deg,rgb(var(--cvm-frost-secondary) / .70),rgb(var(--cvm-frost-rgb) / .54) 62%,rgb(var(--cvm-frost-secondary) / .78));border-color:rgba(255,255,255,.38);}
#cvm-design-preview[data-material="frosted"][data-glass][data-palette][data-background] #cvm-frost-landscape > .cvm-frost-shape--pearl{background:radial-gradient(ellipse at 32% 22%,rgba(255,255,255,.82),rgb(var(--cvm-frost-secondary) / .92) 32%,rgb(var(--cvm-frost-rgb) / .64) 74%,rgb(var(--cvm-frost-rgb) / .44) 100%);}
/* One neutral glass material for the hero card and all six main content sections. */
#cvm-design-preview[data-material="frosted"][data-glass][data-palette][data-background] #top > .hero .trustline,
#cvm-design-preview[data-material="frosted"][data-glass][data-palette][data-background] #top > :is(#so-gehts,#preis,#leistungen,#kanzlei,#ratgeber,#kontakt) > .wrap{
 position:relative;z-index:1;
 background:linear-gradient(130deg,rgba(255,255,255,.10),rgba(255,255,255,0) 56%),rgba(255,255,255,var(--cvm-frost-alpha)) !important;
 border-color:rgba(255,255,255,var(--cvm-frost-edge)) !important;
 box-shadow:inset 0 1px 0 rgba(255,255,255,.80),inset 0 -1px 0 rgba(255,255,255,.16),0 12px 36px rgba(24,35,44,var(--cvm-frost-shadow)) !important;
 backdrop-filter:blur(var(--cvm-frost-blur)) saturate(120%) !important;
 -webkit-backdrop-filter:blur(var(--cvm-frost-blur)) saturate(120%) !important;
}
/* Inner cards remain crisp and visually lighter, without another blur layer. */
#cvm-design-preview[data-material="frosted"][data-glass][data-palette][data-background] #top > :is(#so-gehts,#preis,#ratgeber) :is(.step,#priceCheck,.article){
 background:rgba(255,255,255,var(--cvm-frost-inner-alpha)) !important;
 border-color:rgba(255,255,255,.70) !important;
 box-shadow:inset 0 1px 0 rgba(255,255,255,.70),0 3px 12px rgba(24,35,44,.035) !important;
 backdrop-filter:none !important;-webkit-backdrop-filter:none !important;
}
/* Keep all outer surfaces equally bright on dark canvases, with neutral readable text. */
@supports not ((backdrop-filter:blur(1px)) or (-webkit-backdrop-filter:blur(1px))){
 #cvm-design-preview[data-material="frosted"][data-glass][data-palette][data-background] #top > .hero .trustline,
 #cvm-design-preview[data-material="frosted"][data-glass][data-palette][data-background] #top > :is(#so-gehts,#preis,#leistungen,#kanzlei,#ratgeber,#kontakt) > .wrap{background:#F8FAFC !important;backdrop-filter:none !important;-webkit-backdrop-filter:none !important;}
 #cvm-design-preview[data-material="frosted"][data-glass][data-palette][data-background] .cvm-frost-scene{display:none !important;}
}
@media(prefers-reduced-transparency:reduce){
 #cvm-design-preview[data-material="frosted"][data-glass][data-palette][data-background] #top > .hero .trustline,
 #cvm-design-preview[data-material="frosted"][data-glass][data-palette][data-background] #top > :is(#so-gehts,#preis,#leistungen,#kanzlei,#ratgeber,#kontakt) > .wrap{background:#F8FAFC !important;backdrop-filter:none !important;-webkit-backdrop-filter:none !important;}
 #cvm-design-preview[data-material="frosted"][data-glass][data-palette][data-background] .cvm-frost-scene{display:none !important;}
}

/* Image motifs are actual raster artwork. Color filtering preserves alpha and highlights. */
#cvm-design-preview[data-material="frosted"][data-glass][data-palette][data-background] #cvm-frost-landscape > .cvm-frost-shape--artwork{
 position:absolute;display:block;box-sizing:border-box;pointer-events:none;
 background-repeat:no-repeat;border:0;border-radius:0;box-shadow:none;
}

/* Equal motif opacity in both comparisons; no extra per-image attenuation. Glass rules above are unchanged. */
#cvm-design-preview[data-material="frosted"][data-glass][data-palette][data-background] #cvm-frost-landscape > .cvm-frost-shape{opacity:.82;}

/* Optional mobile clarity: preserve panel fills and inner cards; reduce only outer backdrop blur. */
@media(max-width:759px){
 #cvm-design-preview[data-material="frosted"][data-glass][data-palette][data-background][data-clarity="clear"]{--cvm-frost-blur:12px;}
 #cvm-design-preview[data-material="frosted"][data-glass="strong"][data-palette][data-background][data-clarity="clear"]{--cvm-frost-blur:14px;}
}

/* Live SVG contours: no image transform loop, no rectangle fill, no extra backdrop layer. */
#cvm-design-preview[data-material="frosted"] #cvm-frost-landscape > .cvm-fluid-shape{position:absolute;display:block;pointer-events:none;opacity:.82;}
#cvm-design-preview #cvm-frost-landscape > .cvm-fluid-shape > svg{display:block;width:100%;height:100%;overflow:hidden;}

/* The ribbon artwork is drawn once per viewport, with document-space positions. */
#cvm-frost-landscape > .cvm-ribbon-canvas{position:fixed;inset:0;display:block;width:100%;height:100%;pointer-events:none;}
#cvm-frost-landscape > .cvm-ribbon-fallback{position:absolute;inset:0;overflow:hidden;pointer-events:none;}

/* Static variants are ordinary document-bound artwork; no viewport canvas or scroll updates. */
#cvm-frost-landscape > .cvm-ribbon-static{position:absolute;inset:0;pointer-events:none;overflow:hidden;animation:none !important;transition:none !important;}
#cvm-frost-landscape > .cvm-ribbon-static > img{position:absolute;display:block;max-width:none !important;pointer-events:none;animation:none !important;transition:none !important;mask-image:linear-gradient(to bottom,transparent,#000 24px,#000 calc(100% - 24px),transparent);-webkit-mask-image:linear-gradient(to bottom,transparent,#000 24px,#000 calc(100% - 24px),transparent);}


/* page-s-schwung.css */
/* A static, document-bound ribbon built from the approved material. */
#cvm-frost-landscape > .cvm-page-sweep{position:absolute;left:0;top:0;overflow:hidden;pointer-events:none;animation:none !important;transition:none !important;}
.cvm-page-sweep > :is(img,canvas){position:absolute;display:block;max-width:none !important;filter:url("#cvm-sculpture-tone");opacity:1;pointer-events:none;animation:none !important;transition:none !important;}
.cvm-page-sweep > canvas{left:0;}

/* The source image supplies the same material to every part of the route. */
.cvm-page-sweep > .cvm-page-sweep__hero{display:none !important;}

