#cvm-design-preview[data-background="sage-glacier-white"] body[data-page="index.html"]{background:#F6FAF9;}
#cvm-design-preview[data-background="sage-glacier-white"] body[data-page="index.html"]::before{background:radial-gradient(ellipse at 100% 8%,rgba(167,216,202,.16),transparent 58%),radial-gradient(ellipse at 0% 76%,rgba(228,243,238,.12),transparent 56%);}
#cvm-design-preview[data-palette="sage-glacier"]{
 --cvm-role-tint1:167,216,202;--cvm-role-tint3:198,230,220;--cvm-role-tint2:228,243,238;--cvm-role-solid:246,250,249;
 --cvm-role-ink:#252a30;--cvm-role-muted:#48515b;--cvm-role-accent:#164F49;--cvm-role-display:#33796C;--cvm-role-hero-small:#164F49;--cvm-role-hero-ink:#252a30;--cvm-role-hero-copy:#48515b;
 --cvm-title-main-off:#252a30;--cvm-title-detail-off:#164F49;--cvm-title-number-off:#33796C;--cvm-title-hero-off:#33796C;
 --cvm-title-main-on:#252a30;--cvm-title-detail-on:#164F49;--cvm-title-number-on:#33796C;--cvm-title-hero-on:#33796C;
 --cvm-title-inverseMain-off:#fff;--cvm-title-inverseDetail-off:#E4F3EE;--cvm-title-inverseNumber-off:#A7D8CA;
 --cvm-title-inverseMain-on:#fff;--cvm-title-inverseDetail-on:#E4F3EE;--cvm-title-inverseNumber-on:#A7D8CA;
}
#cvm-design-preview[data-palette="sage-glacier"] #top > .hero h1{color:var(--cvm-role-hero-ink) !important;}
#cvm-design-preview[data-palette="sage-glacier"] #top > .hero .outline{color:var(--cvm-role-display) !important;}
#cvm-design-preview[data-palette="sage-glacier"] #top > .hero .eyebrow{color:var(--cvm-role-hero-small) !important;}
#cvm-design-preview[data-palette="sage-glacier"] #top > .hero .hero-copy{color:var(--cvm-role-hero-copy) !important;}
#cvm-design-preview[data-palette="sage-glacier"] body[data-page="index.html"] :is(.nav-cta,.actions .btn:not(.btn-ghost),.calc-nav .submit,.calc-nav .next,.contact-panel .btn-dark){background:#164F49 !important;color:#F6FAF9 !important;}
#cvm-design-preview[data-palette="sage-glacier"] #top > .hero .btn-ghost{color:#164F49 !important;border-color:rgba(22,79,73,.18) !important;}

/* Targeted usability fixes. The approved palette, glass surfaces, radii,
   backdrop filters, typography and background renderer remain unchanged. */
.skip-link{position:fixed;z-index:200;top:12px;left:16px;transform:translateY(-180%);background:#164F49;color:#F6FAF9;padding:12px 18px;border-radius:12px;}
.skip-link:focus{transform:none;}
#top:focus{outline:none;}
#cvm-design-preview #top :is(.wrap,.calc-copy,.calculator,.question,.field-grid,.field,.trustline>div){min-width:0;}
#cvm-design-preview #top :is(h1,h2,h3,p,.choice-label,.result-summary,.price-row,.consent){overflow-wrap:anywhere;}
#cvm-design-preview #top .trustline{grid-template-columns:repeat(3,minmax(0,1fr));}
#cvm-design-preview #top .trust-art{max-width:100%;}
#cvm-design-preview #top .trust-icon{max-width:100%;}
#cvm-design-preview #top .wizard-head{flex-wrap:wrap;}
#cvm-design-preview #top .choices[role]{min-width:0;}
#cvm-design-preview #priceCheck .question h3{scroll-margin-top:var(--nav-clearance,120px);}
